-- Store-scoped owner and staff roles.
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `description` = VALUES(`description`), `is_system` = VALUES(`is_system`);

-- Copy permissions from system roles when base seed has been run.
SELECT `shop_roles`.`id`, `rp`.`permission_id`
FROM `roles` `shop_roles`
JOIN `roles` `system_roles` ON `system_roles`.`code` = `shop_roles`.`code` AND `system_roles`.`shop_id` IS NULL
JOIN `role_permissions` `rp` ON `rp`.`role_id` = `system_roles`.`id`
WHERE `shop_roles`.`shop_id` IN (SELECT `id` FROM `stores` WHERE `slug` LIKE 'glowora-%' OR `slug` LIKE 'an-nhien-%' OR `slug` LIKE 'lumina-%' OR `slug` LIKE 'moc-an-%' OR `slug` LIKE 'serene-%' OR `slug` LIKE 'aurora-%' OR `slug` LIKE 'la-vie-%' OR `slug` LIKE 'herbal-%' OR `slug` LIKE 'bloom-%' OR `slug` LIKE 'sakura-%');

ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `role_id` = VALUES(`role_id`), `shop_id` = VALUES(`shop_id`);

ON DUPLICATE KEY UPDATE `open_time` = VALUES(`open_time`), `close_time` = VALUES(`close_time`), `is_closed` = VALUES(`is_closed`);

-- Three staff accounts for each demo store.
ON DUPLICATE KEY UPDATE `full_name` = VALUES(`full_name`), `password` = VALUES(`password`), `phone` = VALUES(`phone`), `status` = VALUES(`status`), `updated_at` = NOW();

ON DUPLICATE KEY UPDATE `user_id` = VALUES(`user_id`), `store_id` = VALUES(`store_id`), `specialty` = VALUES(`specialty`), `bio` = VALUES(`bio`), `rating` = VALUES(`rating`), `total_reviews` = VALUES(`total_reviews`), `status` = VALUES(`status`), `updated_at` = NOW();

