INSERT INTO `service_categories` (`id`, `name`, `slug`, `description`, `created_at`, `updated_at`) VALUES
  ('a4fcc6ee-d92c-45fe-955e-ccf9e79d8018', 'Cham soc da mat', 'cham-soc-da-mat', '<p>Cac lieu trinh lam sach, cap am, phuc hoi va tre hoa da mat.</p>', NOW(), NOW()),
  ('6b080aec-2e5a-4327-8054-66c554b9ffa9', 'Spa va massage', 'spa-massage', '<p>Massage thu gian, tri lieu co vai gay, da nong va tinh dau.</p>', NOW(), NOW()),
  ('1ab98804-4324-4f18-805f-00ef8c07439b', 'Duong sinh', 'duong-sinh', '<p>Goi dau duong sinh, cham soc dau, co, vai, gay bang thao moc.</p>', NOW(), NOW()),
  ('2f01ee6f-9bda-4786-a897-5084c941a8b8', 'Cham soc co the', 'cham-soc-co-the', '<p>Tay te bao chet, u duong, tam trang va cham soc body.</p>', NOW(), NOW()),
  ('379f6d4f-910b-4d7a-9e67-f7fbb4d7df8a', 'Triet long', 'triet-long', '<p>Triet long cong nghe lanh va waxing bang sap am diu nhe.</p>', NOW(), NOW()),
  ('2307b047-f377-41fa-a877-9835389c7d8a', 'Nail va mi', 'long-may-mi-mat', '<p>Noi mi, lift mi, cham soc mong va tao kieu tham my tu nhien.</p>', NOW(), NOW())
